<script setup lang="ts">
import { processEnquiry, approveEnquiry, resolveEnquiry, type RecordItem } from '../../lib/workflow'
useHead({ title: 'An enquiry, handled · The AI Toolkit' })
const input = reactive({ id: 'SAFI-001', client: 'Parklands Learning Centre', area: '400', windows: '' })
const records = ref<RecordItem[]>([])
const message = ref('')
const clarified = reactive<Record<string, string>>({})
const plan = reactive({ trigger: '', steps: '', reviewer: '', exception: '', measure: '' })
const planSaved = ref('')
function submit() { const result = processEnquiry(input, records.value); if (result.error) { message.value = result.error; return }; if (result.record) { records.value.unshift(result.record); message.value = 'Record and draft created automatically. Nothing has been sent.' } }
onMounted(() => { try { const saved = localStorage.getItem('dada-workflow-plan'); if (saved) Object.assign(plan, JSON.parse(saved)) } catch {} })
function save() { try { localStorage.setItem('dada-workflow-plan', JSON.stringify(plan)); planSaved.value = 'Saved in this browser.' } catch { planSaved.value = 'Storage unavailable. Copy your plan into your notes.' } }
</script>
<template><main id="main" class="wrap directory"><div class="page-intro"><NuxtLink to="/toolkit" class="back-link">← Back to the toolkit</NuxtLink><p class="eyebrow">08:00 / An enquiry arrives</p><h1 class="display gradient-title">An enquiry, handled.</h1><p class="lead">Submit once. Create a record and a draft. Pause for a person to review.</p></div>
<div class="directory-note"><b>A working local automation</b><p>This example runs fixed rules in your browser. It does not call an AI model, connect to email or send messages. The draft uses a template. ChatGPT handles the separate writing demo; Make, Zapier or n8n can connect authorised business apps after setup.</p><p>Use fictional data here. Demo records disappear on refresh.</p></div>
<div class="workflow-grid"><form class="workflow-form" @submit.prevent="submit"><h2>1. New enquiry</h2><label>Enquiry ID<input v-model="input.id" required /></label><label>Client<input v-model="input.client" required /></label><label>Floor area (m²)<input v-model="input.area" type="number" step="any" min="0.01" required /></label><label>Window details <span class="muted">(leave blank to test a hold)</span><textarea v-model="input.windows" rows="3" placeholder="Count, size, height and access…" /></label><button class="button button-primary" type="submit">Submit enquiry</button><p role="status">{{ message }}</p></form>
<div class="workflow-queue"><h2>2. Review queue</h2><p v-if="!records.length">Submit the form to see the record and draft appear here.</p><article v-for="row in records" :key="row.id" class="queue-record"><span class="pill">{{ row.status }}</span><h3>{{ row.id }} · {{ row.client }}</h3><p>{{ row.area }} m²</p><p class="followup">{{ row.draft }}</p><form v-if="row.missing" class="workflow-form" @submit.prevent="records = records.map(item => item.id === row.id ? resolveEnquiry(item, clarified[row.id] || '') : item)"><label>Confirmed window details<input v-model="clarified[row.id]" required placeholder="Enter the confirmed details" /></label><button class="button button-secondary" type="submit">Resolve missing details</button><p>Updates this record and prepares a new draft for review. It does not create another enquiry.</p></form><button class="button button-secondary" :disabled="row.missing || row.status === 'Approved locally'" @click="records = records.map(item => item.id === row.id ? approveEnquiry(item) : item)">{{ row.status === 'Approved locally' ? 'Approved · nothing sent' : 'Approve draft locally' }}</button></article></div></div>
<section class="section"><p class="eyebrow">17:00 / Make it repeatable</p><h2 class="display">Your first workflow.</h2><p class="lead">Choose one repeated task. Keep the first version small enough to test.</p><form class="workflow-plan" @submit.prevent="save"><label>What starts the work?<input v-model="plan.trigger" placeholder="A new enquiry arrives…" required /></label><label>What happens next?<textarea v-model="plan.steps" rows="3" placeholder="Create record → draft reply → request review" required /></label><label>Who checks it, and what do they check?<input v-model="plan.reviewer" placeholder="Owner checks scope, price and commitments" required /></label><label>What happens if data is missing or a step fails?<input v-model="plan.exception" placeholder="Hold the record and notify the owner" required /></label><label>How will you judge the first five runs?<input v-model="plan.measure" placeholder="No duplicates; no invented prices; fewer manual steps" required /></label><button class="button button-primary">Save my workflow</button><p role="status">{{ planSaved || 'Saved only on this browser; not sent to a server.' }}</p></form><NuxtLink class="text-link" to="/tools#automation">Compare tools for connecting your apps ↗</NuxtLink></section></main></template>
